#include "water.hpp"
#include "simulation.hpp"
#include "surface_audio.hpp"
#include <iostream>
#include <stdexcept>
using namespace ofo;
void need(bool b,const char*m){if(!b)throw std::runtime_error(m);}
int main(int argc,char**argv){try{Material m;m.name="water";need(water_material(m),"water");m.name="watertower";m.texture[0]="Watertank_static.tga";need(!water_material(m),"water tower solid");m.shader=25;need(water_material(m),"native WATER id");auto a=water_animation(0,32),b=water_animation(1,32);need(a.frame!=b.frame&&b.frame<32&&a.u!=b.u,"animated frames UV");need(water_animation(1,32).v==b.v,"pause deterministic");need(water_animation(-1,0).frame==0,"invalid time bounded");if(argc>1){Resources r(argv[1]);need(water_frames(r).size()==32,"32 native frames");size_t maps=0,meshes=0;for(auto&p:track_catalog(r)){auto g=load_geometry(r,p);bool found=false;for(auto&m:g.meshes)if(water_material(g.materials.at(m.material))){found=true;meshes++;}maps+=found;}need(maps>0,"authored water maps");std::cout<<maps<<" water map geometries, "<<meshes<<" mesh batches\n";}Geometry g;g.materials.push_back({"tarmac"});g.materials.push_back({"water"});for(int i=0;i<2;i++){Mesh m;m.material=i;float y=i?.15f:0;m.vertices={{{-100,y,-100}},{{100,y,-100}},{{100,y,100}},{{-100,y,100}}};m.indices={0,2,1,0,3,2};g.meshes.push_back(m);}VehicleConfig c;c.mass=1000;c.inertia={1000,1000,1000};c.lo={-.3f,0,-.5f};c.hi={.3f,.4f,.5f};c.ratios={3,2,1};c.torque_curve={{950,1},{7000,1}};for(int i=0;i<4;i++){auto&w=c.wheels[i];w.mount={i%2?.85f:-.85f,0,i<2?1.f:-1.f};w.width=.4f;w.radius=.3f;w.rest=.3f;w.max=.6f;}Simulation wet(g,c,translate({0,.6f,0}));for(int i=0;i<400;i++)wet.step({});auto s=wet.state();need(s.wheel_contacts[0].grounded&&s.wheel_contacts[0].material==1,"water overlay at grounded contact");need(s.wheel_contacts[0].surface_id==28,"water overlay overrides dry support effect ID");need(std::abs(s.wheel_contacts[0].point.y-.15f)<.01f,"splash origin at water");need(std::abs(s.wheel_contacts[0].water_depth-.15f)<.01f,"actual shallow water depth");SurfaceAudioConfig audio;audio.surfaces.materials.resize(2);audio.surfaces.materials[1].water=true;audio.surfaces.surfaces[2]={};audio.surfaces.surfaces[28].water=true;audio.sounds[11]={};audio.sounds[12]={};auto shallow=s.wheel_contacts;for(auto&w:shallow)w.speed=20;need(surface_audio_control(audio,shallow).voices.count(11),"actual shallow contacts choose low-water audio");auto deep_geometry=g;for(auto&v:deep_geometry.meshes[1].vertices)v.position.y=.45f;Simulation deep(deep_geometry,c,translate({0,.6f,0}));for(int i=0;i<400;i++)deep.step({});auto deep_contacts=deep.state().wheel_contacts;for(auto&w:deep_contacts)w.speed=20;need(surface_audio_control(audio,deep_contacts).voices.count(12),"actual deep contacts choose high-water audio");WheelEffectConfig effects;effects.surfaces[2]={};effects.surfaces[28].water=true;WheelEffects splash(effects);splash.update(shallow,0);splash.update(shallow,.1);need(splash.particle_count()>0&&splash.skid_count()==0,"actual overlay contacts emit water atlas and no dry-road skids");g.meshes.pop_back();Simulation dry(g,c,translate({0,.6f,0}));for(int i=0;i<400;i++)dry.step({});need(std::abs(dry.state().car[13]-s.car[13])<.01f,"water is not solid support");std::cout<<"water tests passed\n";}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
